PAGES.learn=()=>{let S={p:5000,c:300,r:7,y:25},R=3;const calc=()=>{let v=S.p,o=[v];for(let i=1;i<=S.y;i++){v=v*(1+S.r/100)+S.c*12;o.push(v)}return o};
 const p=()=>{const o=calc(),tot=S.p+S.c*12*S.y;$('#cp').innerHTML=svg([{d:o,c:'var(--ac)',w:2}],700,200)+`<div class="big">$${fmt(o[S.y],0)}</div><span class="mu">Contributed $${fmt(tot,0)} · growth $${fmt(o[S.y]-tot,0)}</span>`;
  const d=R-3;$('#ir').innerHTML=[['Bond prices',-d*6,'Duration effect: prices fall as yields rise'],['Stocks',-d*2.5,'Higher discount rate on future earnings'],['Housing',-d*4,'Mortgage costs rise'],['US dollar',d*2,'Rate differentials attract capital'],['Gold',-d*1.5,'Higher opportunity cost']].map(x=>`<div style="margin:8px 0"><div style="display:flex;justify-content:space-between"><span>${x[0]}</span>${pc(x[1])}</div><div style="height:6px;background:var(--s2);border-radius:3px;position:relative"><div style="position:absolute;left:${x[1]>=0?50:50+x[1]*4}%;width:${Math.abs(x[1])*4}%;height:6px;background:${x[1]>=0?'var(--up)':'var(--dn)'}"></div></div><span class="mu">${x[2]}</span></div>`).join('')};
 const sl=(k,l,a,b,s)=>`<label>${l} <b id="l${k}">${S[k]}</b></label><input type=range min=${a} max=${b} step=${s} value=${S[k]} data-k="${k}">`;
 $('#m').innerHTML=`<h2>Quantera Academy</h2><p class="mu">Finance basics, investing, accounting, markets, equity research, trading, derivatives, macro, quant and private markets. Two sample interactive lessons below. Mock illustrative models, not forecasts.</p><div class="pre">${['Finance basics','Investing','Accounting','Markets','Equity research','Trading','Derivatives','Macro','Quant','Private markets'].map(x=>`<span class="chip">${x}</span>`).join('')}</div>
 <div class="g g2"><div class="pan"><h3>How compound interest works <span class="tag">Beginner</span></h3>${sl('p','Initial investment ($)',0,100000,1000)}${sl('c','Monthly contribution ($)',0,3000,50)}${sl('r','Annual return (%)',0,15,.5)}${sl('y','Years',1,40,1)}<div id="cp"></div></div>
 <div class="pan"><h3>What a rate increase does <span class="tag">Intermediate</span></h3><label>Policy rate <b id="lr">${R}%</b></label><input type=range id="rr" min=0 max=8 step=.25 value=${R}><div id="ir"></div></div></div>`;
 document.querySelectorAll('input[data-k]').forEach(i=>i.oninput=()=>{S[i.dataset.k]=+i.value;$('#l'+i.dataset.k).textContent=i.value;p()});$('#rr').oninput=e=>{R=+e.target.value;$('#lr').textContent=R+'%';p()};p()};
/* ===== AI command center ===== */
PAGES.ai=()=>{$('#m').innerHTML=`<h2>Quantera AI command center</h2><p class="mu">Prototype: a rule-based parser turns plain language into a screener. A production system would call a model and cite its sources.</p><div class="pan"><input id="cmd" style="width:100%;background:var(--bg);border:1px solid var(--ln);border-radius:8px;padding:10px" value="Find companies with revenue growth above 20%, debt/equity below 0.5 and market cap above 5 billion"><div class="pre"><button class="btn p" id="run">Run command</button></div><div id="out"></div></div>`;
 $('#run').onclick=()=>{const t=$('#cmd').value.toLowerCase(),f={cap:0,g:0,de:2,pe:70},n=r=>{const m=t.match(r);return m?+m[1]:null};
  const g=n(/growth\D*(\d+)/),d=n(/debt\/equity\D*(\d*\.?\d+)/),c=n(/market cap\D*(\d+)/),pe=n(/p\/e\D*(\d+)/);if(g!=null)f.g=g;if(d!=null)f.de=d;if(c!=null)f.cap=c;if(pe!=null)f.pe=pe;
  $('#out').innerHTML=`<div class="three"><b>Data</b> Parsed filters: ${JSON.stringify(f)}</div><div class="three"><b>Analysis</b> Mapped to screener fields using keyword rules.</div><div class="three"><b>Interpretation</b> Check the filters before relying on the list.</div><a class="btn" href="#/screener/${encodeURIComponent(JSON.stringify(f))}">Open in screener</a>`}};
/* ===== portfolio ===== */
PAGES.portfolio=()=>{const H=[['NVDA',40],['MSFT',30],['SPY',120],['GC=F',6],['BTC-USD',.4],['XOM',50]].map(([s,q])=>{const a=Data.get(s);return{a,q,v:q*a.px,c:Data.chg(s)}}),T=H.reduce((x,h)=>x+h.v,0),day=H.reduce((x,h)=>x+h.v*h.c/100,0);
 $('#m').innerHTML=`<h2>Portfolio <span class="tag">sample holdings</span></h2><div class="big">$${fmt(T,0)} ${pc(day/T*100)}</div><div class="g g2" style="margin-top:16px"><div class="pan"><h3>What is driving my portfolio today?</h3>${[...H].sort((a,b)=>Math.abs(b.v*b.c)-Math.abs(a.v*a.c)).map(h=>`<div style="display:flex;justify-content:space-between;margin:6px 0"><span>${h.a.sym}</span><span>${day?(h.v*h.c/100>=0?'+':'−')+'$'+fmt(Math.abs(h.v*h.c/100),0):''} (${fmt(h.v*h.c/100/Math.abs(day)*100,0)}% of net move)</span></div>`).join('')}<div class="pv">Contribution = position value × day change.</div></div>
 <div class="pan"><h3>Allocation</h3>${H.map(h=>`<div style="margin:6px 0">${h.a.sym} ${fmt(h.v/T*100,1)}%<div style="height:6px;background:var(--ac);width:${h.v/T*100}%;border-radius:3px"></div></div>`).join('')}</div></div>`};
