PAGES.terminal=()=>{const all=['Chart','Watchlist','News','Screener','Market map'];let on=['Chart','Watchlist','News'];const p=()=>{$('#tm').innerHTML=on.map(k=>`<div class="pan"><div style="display:flex;justify-content:space-between"><h3>${k}</h3><a class="mu" onclick="rm_('${k}')">remove</a></div>${k=='Chart'?svg([{d:Data.hist('SPY',252),c:'var(--ac)'}],500,200):k=='Watchlist'?Data.all().slice(0,6).map(a=>`<div style="display:flex;justify-content:space-between"><a href="#/asset/${a.sym}">${a.sym}</a>${pc(Data.chg(a.sym))}</div>`).join(''):`<span class="mu">${k} panel: wired to the same Data layer. Drag and resize is the next milestone.</span>`}</div>`).join('');$('#ad').innerHTML=all.filter(k=>!on.includes(k)).map(k=>`<button class="chip" onclick="ad_('${k}')">+ ${k}</button>`).join('')};
 $('#m').innerHTML='<h2>Quantera Terminal</h2><p class="mu">Workspace: US Equity Research (saved workspaces planned).</p><div class="pre" id="ad"></div><div class="g g3" id="tm"></div>';window.rm_=k=>{on=on.filter(x=>x!=k);p()};window.ad_=k=>{on.push(k);p()};p()};
