const art=(s,a,b)=>{const r=rng(hash(s)+1),i=hash(s);let o=`<svg viewBox="0 0 400 220" preserveAspectRatio="xMidYMid slice" style="width:100%;height:100%;display:block"><defs><linearGradient id="g${i}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" style="stop-color:${a}"/><stop offset="1" style="stop-color:${b}"/></linearGradient></defs><rect width="400" height="220" fill="url(#g${i})"/>`;
 for(let k=0;k<3;k++)o+=`<circle cx="${r()*400}" cy="${r()*110}" r="${14+r()*46}" fill="none" stroke="#fff" stroke-opacity=".28"/>`;
 for(let k=0;k<6;k++){let d='M0 220';for(let x=0;x<=400;x+=20)d+=`L${x} ${105+k*15+Math.sin(x/58+r()*6+k)*(16+r()*28)}`;o+=`<path d="${d}L400 220Z" fill="var(--bg)" opacity="${.14+k*.11}"/>`}return o+'</svg>'};
const area=(d,c,id,w=700,h=260)=>{const mn=Math.min(...d),mx=Math.max(...d),p=d.map((v,i)=>(i?'L':'M')+(i/(d.length-1)*w).toFixed(1)+' '+(10+(1-(v-mn)/(mx-mn||1))*(h-20)).toFixed(1)).join('');
 return `<svg viewBox="0 0 ${w} ${h}" style="width:100%;height:auto;display:block"><defs><linearGradient id="a${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:${c};stop-opacity:.4"/><stop offset="1" style="stop-color:${c};stop-opacity:0"/></linearGradient></defs>${[.25,.5,.75].map(t=>`<line x1="0" x2="${w}" y1="${h*t}" y2="${h*t}" stroke="var(--ln)"/>`).join('')}<path d="${p}L${w} ${h}L0 ${h}Z" fill="url(#a${id})"/><path d="${p}" fill="none" stroke="${c}" stroke-width="2"/></svg>`};
const LIVE={};let iv;
const strip=()=>{const h=Data.all().map(a=>`<span>${a.sym} <b data-p="${a.sym}">${fmt(a.px)}</b> ${pc(Data.chg(a.sym))}</span>`).join('');return `<div class="strip"><div class="trk">${h+h}</div></div>`};
const live=()=>{clearInterval(iv);iv=setInterval(()=>document.querySelectorAll('[data-p]').forEach(e=>{const a=Data.get(e.dataset.p);LIVE[a.sym]=(LIVE[a.sym]||1)*(1+(Math.random()-.5)*.0007);e.textContent=fmt(a.px*LIVE[a.sym])}),1500)};
