 id=k=>N.findIndex(n=>n[0]==k),pos=N.map((_,i)=>{const y=1-2*(i+.5)/N.length,r=Math.sqrt(1-y*y),t=i*2.399;return[r*Math.cos(t)*.9,y*.9,r*Math.sin(t)*.9]});let sel=1,sh=1,IM={};
 const prop=()=>{IM={};IM[N[sel][0]]=sh;let fr=[[N[sel][0],sh]];for(let h=0;h<3;h++){const nx=[];fr.forEach(([a,v])=>E.filter(e=>e[0]==a).forEach(e=>{const w=v*e[2]*.6;IM[e[1]]=(IM[e[1]]||0)+w;nx.push([e[1],w])}));fr=nx}};
 $('#m').innerHTML=`<h2 style="font-size:40px">Concept map</h2><p class="mu" style="max-width:640px">How macro and market forces connect. Click a concept, apply a shock, and watch the effect travel through the system. Drag to rotate, scroll to zoom.</p><div class="g" style="grid-template-columns:2fr 1fr"><div class="pan" style="padding:0"><canvas id="bc" style="width:100%;aspect-ratio:16/11;display:block;touch-action:none"></canvas></div><div class="pan"><h3 id="bt"></h3><p class="mu" id="bd"></p><label>Shock size <b id="bs"></b></label><input id="sh" type=range min=-2 max=2 step=.5 value=1><div id="bl" style="margin-top:10px"></div><div class="pv">Qualitative model with illustrative weights (60% pass-through per step, 3 steps). Not a forecast.</div></div></div>`;
 const pan=()=>{prop();const n=N[sel];$('#bt').innerHTML=n[1];$('#bd').innerHTML=n[2]+` <a href="${n[3]}" style="color:var(--ac)">Learn more</a>`;$('#bs').textContent=(sh>0?'+':'')+sh;
  $('#bl').innerHTML=Object.entries(IM).filter(([k])=>k!=n[0]).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).slice(0,7).map(([k,v])=>`<div style="display:flex;justify-content:space-between;cursor:pointer" onclick="BN_(${id(k)})"><span>${N[id(k)][1]}</span><span class="${v>=0?'up':'dn'}">${v>=0?'▲':'▼'} ${fmt(Math.abs(v),2)}</span></div>`).join('')+'<div class="mu" style="margin-top:8px">'+E.filter(e=>e[0]==n[0]).map(e=>`${N[id(e[1])][1]}: ${e[3]}`).join('<br>')+'</div>'};
