 const st=view($('#bc'),(x,Q,s,W,H)=>{const P=pos.map(Q);E.forEach(e=>{const a=P[id(e[0])],b=P[id(e[1])],hot=IM[e[0]]&&IM[e[1]];x.strokeStyle=hot?(e[2]>0?'rgba(79,209,165,.6)':'rgba(240,112,122,.6)'):'rgba(143,150,170,.15)';x.lineWidth=hot?1.6:1;x.beginPath();x.moveTo(a[0],a[1]);x.lineTo(b[0],b[1]);x.stroke()});
  P.map((p,i)=>[p,i]).sort((a,b)=>b[0][2]-a[0][2]).forEach(([p,i])=>{const v=IM[N[i][0]]||0;x.globalAlpha=.55+.45*p[3]/1.3;x.fillStyle=v>0.05?'#4fd1a5':v<-0.05?'#f0707a':'#8e97a8';x.beginPath();x.arc(p[0],p[1],(5+Math.min(Math.abs(v)*7,16))*p[3],0,7);x.fill();if(i==sel){x.strokeStyle='#c8a96a';x.lineWidth=2;x.stroke()}x.globalAlpha=1;x.fillStyle='#f2eee6';x.font='12px Manrope,sans-serif';x.fillText(N[i][1],p[0]+10,p[1]+4);s.pts.push([p[0],p[1],i])})});
