bs:{s:[['S','Stock price ($)',20,200,1,100],['K','Strike price ($)',20,200,1,100],['d','Days to expiry',5,365,5,60],['v','Volatility (%)',5,100,1,30],['r','Interest rate (%)',0,8,.25,4]],f:S=>{const T=S.d/365,v=S.v/100,r=S.r/100,sq=Math.sqrt(T),d1=(Math.log(S.S/S.K)+(r+v*v/2)*T)/(v*sq),d2=d1-v*sq,call=S.S*NC(d1)-S.K*Math.exp(-r*T)*NC(d2),put=S.K*Math.exp(-r*T)*NC(-d2)-S.S*NC(-d1);return `<div class="big">Call $${fmt(call)} · Put $${fmt(put)}</div>`+KV('Delta (call)',fmt(NC(d1),2))+KV('Gamma',fmt(pdf(d1)/(S.S*v*sq),3))+KV('Theta per day (call)','$'+fmt((-S.S*pdf(d1)*v/(2*sq)-r*S.K*Math.exp(-r*T)*NC(d2))/365,3))+KV('Vega per 1% volatility','$'+fmt(S.S*pdf(d1)*sq/100,3))+'<div class="pv">Educational model with fixed assumptions: no dividends, European exercise.</div>'}},
sharpe:{s:[['r','Annual return (%)',-10,40,.5,12],['rf','Risk-free rate (%)',0,8,.25,3],['v','Volatility (%)',2,50,.5,16],['dv','Downside volatility (%)',1,40,.5,10]],f:S=>KV('Sharpe ratio',fmt((S.r-S.rf)/S.v,2))+KV('Sortino ratio',fmt((S.r-S.rf)/S.dv,2))+'<p class="mu">Sharpe divides excess return by total volatility. Sortino uses only downside volatility, so upside swings are not punished.</p>'},
kelly:{s:[['p','Win probability (%)',30,80,1,55],['b','Win size / loss size',.5,4,.1,1],['f','Fraction of capital bet (%)',1,100,1,10]],f:S=>{const p=S.p/100,k=Math.max(0,p-(1-p)/S.b),g=x=>p*Math.log(1+S.b*x)+(1-p)*Math.log(1-x),arr=Array.from({length:99},(_,i)=>g((i+1)/100)*100);return svg([{d:arr,c:'var(--ac)',w:2.5}],700,180)+KV('Kelly fraction',fmt(k*100,1)+'% of capital')+KV(`Growth per bet at ${S.f}%`,fmt(g(S.f/100)*100,2)+'%')+`<p class="mu">${S.f/100>2*k?'You are betting more than twice Kelly: growth turns negative.':S.f/100>k?'Above Kelly: more risk for less growth.':'At or below Kelly: safer, close to the best growth.'} Across: fraction bet, 1% to 99%.</p>`}},
