 const tb=()=>{$('#mt').innerHTML=[['gainers','Top gainers'],['losers','Top losers'],['active',D&&D.movers&&D.movers.universe?'Biggest moves':'Most active'],...(D&&D.movers&&D.movers.all?[['all','Popular ('+D.movers.all.length+')']]:[]),['dir','All US stocks']].map(t=>`<button class="chip ${tab==t[0]?'on':''}" onclick="MT_('${t[0]}')">${t[1]}</button>`).join('')+(D&&D.movers&&D.movers.updated?`<span class="mu" style="margin-left:auto;font-size:12px">Updated ${esc(isNaN(Date.parse(D.movers.updated))?D.movers.updated:new Date(D.movers.updated).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}))}</span>`:'');
  $('#mb').innerHTML=MKLIST(D,tab)};
