document.head.insertAdjacentHTML('beforeend','<style>select,input[type=text],input[type=email],input[type=search],input[type=number],textarea{color-scheme:dark;background:var(--s2)!important;color:var(--tx)!important;border:1px solid var(--ln)!important;border-radius:10px!important;padding:10px 12px!important;font:inherit;outline:0;box-sizing:border-box}select:focus,input:focus{border-color:var(--ac)!important}select option{background:var(--s1);color:var(--tx)}.pan{padding:22px!important}.g{gap:22px}.pre{gap:8px 10px;align-items:center}label{margin:16px 0 6px;font-size:13px}.stat{padding:12px 0}h3{margin:0 0 14px;font-size:16px}table th,table td{padding:12px 10px}.chip{padding:6px 12px;border-radius:8px;font-size:13px}.addrow{display:flex;gap:10px}.sug{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}#tb{gap:8px 10px;padding-bottom:14px;border-bottom:1px solid var(--ln);margin-bottom:16px!important}#dt{display:grid;grid-template-columns:repeat(2,40px);gap:6px;align-content:start}#dt .chip{padding:8px 0;text-align:center;min-width:0!important}#dt>div{grid-column:1/-1}#pp,#ed{border-radius:12px;padding:16px!important}.body{padding:38px 34px 110px}@media(max-width:800px),(pointer:coarse) and (max-height:500px){.pan{padding:16px!important}.body{padding:22px 14px 110px}.addrow{flex-direction:column}#dt{grid-template-columns:repeat(4,38px)}}</style>');
