 PT0={cash:100000,pos:{},hist:[]},
 saveWL=()=>SS('q_wl',[...WL]);
const checkAlerts=()=>{const A=LS('q_al',[]);let ch=0;A.forEach(a=>{if(a.fired)return;const p=LP(a.sym);if(p==null)return;if(a.op=='>'?p>=a.px:p<=a.px){a.fired=Date.now();ch=1;const m=`${a.sym} is ${a.op=='>'?'above':'below'} ${fmt(a.px)} (now ${fmt(p)})`;qtoast('<b>Price alert</b><br>'+esc(m));try{if(window.Notification&&Notification.permission=='granted')new Notification('Quantera alert',{body:m})}catch(e){}}});if(ch)SS('q_al',A);return ch};
