const lp22=PAGES.lesson;PAGES.lesson=id=>{lp22(id);const L=LES.find(x=>x[0]==id);if(!L)return;const X=LX[id],sp=document.querySelector('#m .g.sp'),qp=document.querySelector('#m .g.g2');
 const Q=[[L[8][0],L[8][1],L[8][2],X?'':null],...(X?X.q:[])];
 if(X&&sp){sp.insertAdjacentHTML('beforebegin',`<div class="lsteps"><a onclick="document.getElementById('lx1').scrollIntoView({behavior:'smooth'})">1 · Learn</a><a onclick="document.getElementById('lx2').scrollIntoView({behavior:'smooth'})">2 · Try it</a><a onclick="document.getElementById('lx3').scrollIntoView({behavior:'smooth'})">3 · Quiz</a></div><div class="pan lx" id="lx1"><h3 style="margin-top:0">The idea</h3><p>${X.i}</p><h3>How it works</h3><ul>${X.h.map(x=>`<li>${x}</li>`).join('')}</ul><h3>Worked example</h3><div class="ex">${X.e}</div><h3>Common mistakes</h3><ul>${X.m.map(x=>`<li>${x}</li>`).join('')}</ul><h3>Key takeaways</h3><div class="kt">${X.k.map(x=>`<div><b>✓</b><span>${x}</span></div>`).join('')}</div></div><h3 id="lx2" style="margin:26px 0 4px">Try it yourself</h3><p class="mu" style="margin:0 0 10px">Move the sliders and watch the idea from the lesson play out.</p>`)}
 if(qp){const qz=qp.querySelector('.pan');let right=new Set();qz.id='lx3';qz.classList.add('qz');
  qz.innerHTML=`<h3>Quiz: check what you learned</h3><p class="mu" style="margin:0">${Q.length} questions. Each answer is explained.</p>${Q.map((q,n)=>`<div class="qq">${n+1}. ${q[0]}</div>${q[1].map((o,i)=>`<button class="op" data-q="${n}" data-i="${i}">${o}</button>`).join('')}<div class="why" id="qw${n}" style="display:none"></div>`).join('')}<div id="qf" style="margin-top:12px"></div>`;
  qz.querySelectorAll('.op').forEach(b=>b.onclick=()=>{const n=+b.dataset.q,i=+b.dataset.i,q=Q[n],ok=i==q[2];qz.querySelectorAll(`.op[data-q="${n}"]`).forEach(x=>x.classList.remove('ok','no'));b.classList.add(ok?'ok':'no');
   const w=$('#qw'+n);w.style.display='block';w.innerHTML=(ok?'<span class="up">Correct.</span> ':'<span class="dn">Not quite.</span> ')+(ok?(q[3]||'Nice work.'):'Try another option.'+(q[3]?' Hint: re-read “How it works” above.':''));
   if(ok)right.add(n);if(right.size==Q.length){DONE.add(id);saveDone_();ACT_('lesson');$('#qf').innerHTML=`<span class="up"><b>Lesson complete.</b></span> <span class="mu" style="font-size:12px">${SAVENOTE()}</span> ${(()=>{const k=LES.findIndex(x=>x[0]==id),nx=LES[k+1];return nx?`<a class="btn p" href="#/lesson/${nx[0]}" style="margin-left:10px">Next: ${nx[1]} →</a>`:''})()}`;track('lesson_done')}else $('#qf').innerHTML=`<span class="mu">${right.size} of ${Q.length} correct</span>`})}};

