 $('#m').innerHTML=`<div class="pan"><div id="wsr"></div><div class="mu" style="font-size:12px;margin-top:6px">Search any company, ETF or index on any exchange, e.g. Toyota, HSBC, Reliance, Nikkei.</div></div><div class="wrg" id="wrg"></div><div id="wcg">${EMPTY('Loading world markets…')}</div><div class="wsn" style="margin-top:14px">Prices from Yahoo Finance, delayed about 15 minutes outside the US. Local currency.</div>`;
 AddBox($('#wsr'),s=>go('#/trade/'+encodeURIComponent(s)),'Search stocks, ETFs and indexes worldwide');
