/* ===== v26c: Geopolitics, war, tariffs, elections, rates and oil — how the news is moving markets, with today's actual moves ===== */
const GEOSET={
 war:{n:'War & geopolitics',re:/\b(war|wars|military|missiles?|invasion|invade|troops|airstrikes?|drone strikes?|ceasefire|conflict|nato|ukraine|russia|israel|gaza|hamas|hezbollah|iran|taiwan strait|north korea|pentagon|geopolitic\w*|sanctions?|attack on)\b/i,
  a:[['CL=F','Oil','up'],['GC=F','Gold','up'],['^GSPC','S&P 500','down'],['^VIX','Fear index (VIX)','up'],['ITA','Defense stocks','up'],['JETS','Airlines','down'],['^TNX','10-yr Treasury yield','down'],['DX-Y.NYB','US dollar','up']],
  why:['<b>Oil</b> jumps when fighting threatens oil fields or shipping routes, because supply could be cut.','<b>Gold, the dollar and Treasuries</b> are “safe havens”: worried investors buy them, which also pushes bond yields down.','<b>Stocks</b> usually dip and the <b>VIX</b> (the market’s fear gauge) rises, because uncertainty makes investors sell riskier assets.','<b>Defense companies</b> can rise on expectations of more military spending; <b>airlines</b> fall on higher fuel costs and fewer travellers.']},
 trade:{n:'Trade & tariffs',re:/\b(tariffs?|trade war|trade deal|trade talks|export controls?|import duties|customs duties|trade deficit)\b/i,
  a:[['^GSPC','S&P 500','down'],['FXI','China stocks','down'],['XRT','Retailers','down'],['SOXX','Chip stocks','down'],['DX-Y.NYB','US dollar','up'],['GC=F','Gold','up']],
  why:['<b>Retailers and importers</b> pay more for goods from abroad, which squeezes profits or raises prices for shoppers.','<b>Exporters and Chinese companies</b> can lose customers when the other side hits back.','<b>Chipmakers</b> are exposed to export controls and global supply chains.','Higher prices can keep <b>inflation and interest rates</b> up for longer, which weighs on the whole market.']},
 rates:{n:'Fed & rates',re:/\b(fed|federal reserve|powell|rate cut|rate hike|cuts rates|raises rates|interest rates?|inflation|cpi|pce|central bank|ecb|bank of england|bank of japan)\b/i,
  a:[['^TNX','10-yr Treasury yield',''],['^GSPC','S&P 500',''],['QQQ','Nasdaq 100 (growth stocks)',''],['KRE','Regional banks',''],['DX-Y.NYB','US dollar',''],['GC=F','Gold','']],
  why:['Higher rates make future profits worth less today, so <b>growth and tech stocks</b> are the most sensitive.','<b>Banks</b> can earn more on loans, but higher rates also hurt the bonds they own.','The <b>dollar</b> tends to rise with US rates, and <b>gold</b> (which pays no interest) tends to fall when yields rise.','Markets move on <b>surprises</b>: a cut or hike everyone expected may barely move prices.']},
 oil:{n:'Oil & energy',re:/\b(opec|oil price|oil prices|crude|brent|oil supply|oil output|barrel|refiner\w*|natural gas|lng)\b/i,
  a:[['CL=F','Oil (WTI)',''],['BZ=F','Brent oil',''],['XLE','Energy stocks',''],['JETS','Airlines',''],['^GSPC','S&P 500','']],
  why:['<b>Energy companies</b> earn more when oil is expensive, so they usually move with the oil price.','<b>Airlines, shipping and chemical makers</b> pay more for fuel, so they often fall when oil rises.','Expensive oil feeds into <b>inflation</b>, which can keep interest rates higher for longer.']},
 politics:{n:'Politics & elections',re:/\b(election|elections|voters|campaign|congress|senate|white house|government shutdown|debt ceiling|executive order|parliament|prime minister|president)\b/i,
  a:[['^GSPC','S&P 500',''],['^VIX','Fear index (VIX)',''],['^TNX','10-yr Treasury yield',''],['DX-Y.NYB','US dollar',''],['GC=F','Gold','']],
  why:['Politics changes <b>taxes, spending and regulation</b>, which can help or hurt whole industries.','<b>Uncertainty</b> (close elections, shutdowns, debt-ceiling fights) tends to raise the VIX and push some investors toward gold and bonds.','Investors try to price in <b>which sectors win or lose</b> from likely policies, for example energy, healthcare, banks or clean energy.']}};
const GEOCAT=a=>{const t=(a&&(a.title||'')+' '+(a.summary||a.description||a.snippet||''))||'';for(const k of ['war','trade','oil','rates','politics'])if(GEOSET[k].re.test(t))return k;return null};
let GEOQ={},GEOT=0;const GEOSYMS=[...new Set(Object.values(GEOSET).flatMap(g=>g.a.map(x=>x[0])))];
const geoLoad=()=>{if(!QLIVE.market||Date.now()-GEOT<60000)return;GEOT=Date.now();jf('/api/quotes?symbols='+GEOSYMS.slice(0,25).map(encodeURIComponent).join(',')).then(({ok,b})=>{if(ok)b.quotes.forEach(q=>GEOQ[q.symbol]=q)}).catch(()=>{})};
(function geoWait(n){if(QLIVE.ok){geoLoad();setInterval(geoLoad,60000);return}if(n<60)setTimeout(()=>geoWait(n+1),500)})(0);
const GEOMV=x=>{const q=GEOQ[x[0]];if(!q||q.changePct==null)return null;const c=+q.changePct;return {c,ok:x[2]?(x[2]=='up'?c>0:c<0):null,v:x[0]=='^TNX'?fmt(+q.price,2)+'%':x[0]=='^VIX'?fmt(+q.price,1):null}};
const GEOIMPACT=a=>{const k=GEOCAT(a);if(!k)return'';const g=GEOSET[k],M=g.a.map(x=>[x,GEOMV(x)]).filter(z=>z[1]);
 const exp=M.filter(z=>z[1].ok!=null),hit=exp.filter(z=>z[1].ok).length;
 const verdict=!M.length?'<span class="mu">Today’s market moves will appear here in a moment.</span>':!exp.length?'':hit>=Math.ceil(exp.length*.6)?`<b>Markets are reacting the way they usually do to this kind of news</b> (${hit} of ${exp.length} moves point the usual way).`:hit<=Math.floor(exp.length*.3)?'<b>Markets are mostly shrugging this off so far</b>: most moves are going against the usual pattern, so other news may matter more today.':'<b>The reaction is mixed</b>: some markets are moving the usual way, others aren’t.';
 return `<div class="sx"><p style="margin:0 0 8px"><span class="tag">${esc(g.n)}</span> ${verdict}</p>${M.length?`<div class="nrx" style="display:flex;flex-wrap:wrap;gap:6px 14px;margin:0 0 10px">${M.map(([x,m])=>`<a href="#/trade/${encodeURIComponent(x[0])}" class="${m.c>=0?'up':'dn'}" title="${x[2]?'Usually '+(x[2]=='up'?'rises':'falls')+' on this kind of news':''}"><span class="mu">${esc(x[1])}</span> <b>${m.v?m.v+' ':''}${m.c>=0?'+':'−'}${fmt(Math.abs(m.c))}%</b>${m.ok==null?'':m.ok?' ✓':' ✗'}</a>`).join('')}</div>`:''}<ul style="margin:0">${g.why.map(w=>`<li>${w}</li>`).join('')}</ul><div class="wsn">✓ = moving the way it usually does on this kind of news. Today’s moves can also reflect other news; education, not investment advice.</div></div>`};
const GEOLINE=a=>{const k=GEOCAT(a);if(!k||k=='politics')return'';const g=GEOSET[k],M=g.a.slice(0,5).map(x=>[x,GEOMV(x)]).filter(z=>z[1]);if(!M.length)return'';return `<div class="nrx"><span class="mu">Markets today:</span> ${M.map(([x,m])=>`<a href="#/trade/${encodeURIComponent(x[0])}" class="${m.c>=0?'up':'dn'}">${esc(x[1])} <b>${m.c>=0?'+':'−'}${fmt(Math.abs(m.c))}%</b></a>`).join(' · ')}</div>`};

