const D2=v=>(v<0?'−':'')+'$'+fmt(Math.abs(v),2),SG2=v=>(v>=0?'+':'−')+'$'+fmt(Math.abs(v),2);
/* Portfolio card: value, all-time return, a line of the value day by day, cash / invested / open and realized P/L */
/* Portfolio card (Robinhood-style): big value, change over the chosen range, a chart you can scrub with a finger or mouse, range buttons */
const PCRG_=[['1W',7,'Past week'],['1M',30,'Past month'],['3M',91,'Past 3 months'],['1Y',365,'Past year'],['All',1e9,'All time']];let PCRG='1M';
const PCPTS=(H,start,rg)=>{const R=PCRG_.find(r=>r[0]==rg)||PCRG_[1],cut=new Date(Date.now()-R[1]*864e5).toISOString().slice(0,10);let P=H.filter(x=>x.d>=cut).map(x=>({d:x.d,v:x.v}));if(rg=='All'||P.length<2){P=H.map(x=>({d:x.d,v:x.v}));if(rg=='All'||P.length<2)P=[{d:'',v:start},...P]}return P};
const PCCH=(P,eq)=>{if(P.length<2)return `<div class="pce">Your portfolio’s value will be charted here, day by day, as you trade.</div>`;const vs=P.map(p=>p.v),lo=Math.min(...vs),hi=Math.max(...vs),r=hi-lo||1,W=600,Hh=150,X=i=>i/(P.length-1)*W,Y=v=>8+(1-(v-lo)/r)*(Hh-16),up=P[P.length-1].v>=P[0].v,c=up?'var(--up)':'var(--dn)',id='pcg'+Math.random().toString(36).slice(2,7),d=P.map((p,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(p.v).toFixed(1)).join(' ');
 return `<svg viewBox="0 0 ${W} ${Hh}" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${c}" stop-opacity=".22"/><stop offset="1" stop-color="${c}" stop-opacity="0"/></linearGradient></defs><path d="${d} L${W} ${Hh} L0 ${Hh}Z" fill="url(#${id})"/><path d="${d}" fill="none" stroke="${c}" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linejoin="round"/><line x1="0" x2="${W}" y1="${Y(P[0].v)}" y2="${Y(P[0].v)}" stroke="var(--mu)" stroke-opacity=".35" stroke-dasharray="3 4" vector-effect="non-scaling-stroke"/></svg><i class="pcx"></i><b class="pcd" style="background:${c}"></b>`};
const PCCHG=(P,rg,i)=>{if(P.length<2)return '';const a=P[0].v,b=P[i==null?P.length-1:i].v,ch=b-a,pc=a?ch/a*100:0,R=PCRG_.find(r=>r[0]==rg)||PCRG_[1];return `<span class="${ch>=0?'up':'dn'}"><span aria-hidden="true">${ch>=0?'▲':'▼'}</span> ${D2(Math.abs(ch)).replace('−','')} (${fmt(Math.abs(pc),2)}%)</span> <span class="mu">${i==null?R[2]:new Date(P[i].d+'T12:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span>`};
