const LPX=(seed,n,drift=.0007,vol=.016)=>{const r=rng(seed),o=[100];for(let i=1;i<n;i++)o.push(o[i-1]*(1+drift+(r()-.5)*vol*2));return o};
const LVOL=(seed,n)=>{const r=rng(seed+3);return Array.from({length:n},()=>.5+r())};
const LMA=(a,n)=>a.map((_,i)=>i<n-1?null:a.slice(i-n+1,i+1).reduce((x,y)=>x+y,0)/n);
const LEM=(a,n)=>{const k=2/(n+1);let e=a[0];return a.map(v=>e=v*k+e*(1-k))};
const LCH=(S,o={})=>{const h=o.h||240,w=700,A=S.flatMap(s=>s.d.filter(v=>v!=null)),L=(o.lines||[]).map(l=>l.v),mn=o.mn??Math.min(...A,...L),mx=o.mx??Math.max(...A,...L),Y=v=>10+(1-(v-mn)/(mx-mn||1))*(h-20),n=Math.max(...S.map(s=>s.d.length)),X=i=>i/(n-1)*w;
 return `<svg class="lss" viewBox="0 0 ${w} ${h}" style="width:100%;height:auto;display:block">${(o.lines||[]).map(l=>`<line x1="0" x2="${w}" y1="${Y(l.v)}" y2="${Y(l.v)}" stroke="${l.c}" stroke-dasharray="5 4"/><text x="6" y="${Y(l.v)-4}">${l.t}</text>`).join('')}${(o.bars||[]).map((v,i)=>`<rect x="${X(i)-1.5}" y="${Math.min(Y(v),Y(0))}" width="3" height="${Math.abs(Y(v)-Y(0))}" fill="${v>=0?'var(--up)':'var(--dn)'}" opacity=".55"/>`).join('')}${S.map(s=>{let p='',on=0;s.d.forEach((v,i)=>{if(v==null){on=0;return}p+=(on?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1);on=1});return `<path d="${p}" fill="none" stroke="${s.c}" stroke-width="${s.w||1.8}" ${s.dash?'stroke-dasharray="5 4"':''}/>`}).join('')}</svg>`};
