PAGES.brief=()=>{track('view_brief');$('#m').innerHTML=`<div class="brf"><div id="brb">${EMPTY('Putting today’s brief together…')}</div></div>`;
 if(!QLIVE.market){$('#brb').innerHTML=EMPTY('The daily brief needs live data, which is unavailable right now.');return}
 Promise.all([jf('/api/markets'),jf('/api/news?limit=10').catch(()=>({ok:false})),jf('/api/calendar?type=earnings').catch(()=>({ok:false}))]).then(([M,N,C])=>{const el=document.getElementById('brb');if(!el)return;if(!M.ok){el.innerHTML=EMPTY('Today’s brief is unavailable right now. Check back soon.');return}const b=M.b;
  const ix=(b.indices||[]).map(x=>({sym:x.levelSymbol||x.symbol,name:BRN[x.symbol]||x.symbol,pc:x.level!=null?x.levelChangePct:x.changePct,px:x.level!=null?x.level:x.price})).filter(x=>x.pc!=null),sp=ix[0],nq=ix[1];
  const as=Object.fromEntries((b.assets||[]).map(a=>[a.symbol,a])),btc=(b.crypto||[]).find(c=>c.from=='BTC'),gold=as['GC=F'],oil=as['CL=F'],ty=as['^TNX'];
  const day=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}),P=v=>`<b class="${v>=0?'up':'dn'}">${v>=0?'+':'−'}${fmt(Math.abs(v))}%</b>`;
  let lead=sp?`US stocks ${brW(sp.pc)} today: the S&P 500 ${P(sp.pc)}${nq?` and the Nasdaq 100 ${P(nq.pc)}`:''}.`:'';
  const ex=[];if(gold&&gold.changePct!=null)ex.push(`gold ${P(gold.changePct)}`);if(oil&&oil.changePct!=null)ex.push(`oil ${P(oil.changePct)}`);if(btc&&btc.changePct!=null)ex.push(`Bitcoin ${P(btc.changePct)}`);if(ex.length)lead+=` Elsewhere, ${ex.join(', ')}.`;
  const g=(b.movers&&b.movers.gainers||[]).slice(0,4),l=(b.movers&&b.movers.losers||[]).slice(0,4),T=[...ix.slice(0,4).map(x=>[x.name,fmt(x.px),x.pc,x.sym])];if(gold)T.push(['Gold',fmt(gold.price),gold.changePct,'GC=F']);if(oil)T.push(['Oil (WTI)',fmt(oil.price),oil.changePct,'CL=F']);if(btc)T.push(['Bitcoin',fmt(btc.rate),btc.changePct,'BTC-USD']);if(ty)T.push(['10-year yield',fmt(ty.price,2)+'%',ty.changePct,'^TNX']);
  const mv=L=>L.map(x=>`<a href="#/asset/${encodeURIComponent(x.symbol)}"><span><b style="color:var(--tx)">${esc(x.symbol)}</b> ${esc(x.name||'')}</span>${P(x.changePct)}</a>`).join('')||'<div class="mu">—</div>';
  const news=N.ok?(N.b.articles||[]).slice(0,6):[],ern=C.ok?(C.b.items||[]).filter(x=>x.date==new Date().toISOString().slice(0,10)).slice(0,8):[];
  el.innerHTML=`<div class="mu" style="font-size:13px;letter-spacing:.06em;text-transform:uppercase">${esc(day)} · ${QLIVE.marketOpen?'US market open':'US market closed'}</div><p class="bl">${lead}</p>
  <div class="bt">${T.map(t=>`<a href="#/asset/${encodeURIComponent(t[3])}"><span>${esc(t[0])}</span><b>${t[1]}</b>${t[2]!=null?P(t[2]):''}</a>`).join('')}</div>
  <div class="g g2"><div class="pan"><h3>Biggest risers</h3><div class="mv">${mv(g)}</div></div><div class="pan"><h3>Biggest fallers</h3><div class="mv">${mv(l)}</div></div></div>
  ${news.length?`<div class="pan" style="margin-top:16px"><h3 style="display:flex;justify-content:space-between">Top stories <a href="#/news" style="font-size:13px;font-weight:400">All news →</a></h3><div class="ns">${news.map(a=>`<a href="${a.id?'#/story/'+encodeURIComponent(a.id):esc(a.url)}"${a.id?'':' target="_blank" rel="noopener noreferrer"'}>${esc(a.title)}<small>${esc(a.source||'')}${a.publishedAt?' · '+new Date(a.publishedAt).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):''}</small></a>`).join('')}</div></div>`:''}
  ${ern.length?`<div class="pan" style="margin-top:16px"><h3>Reporting earnings today</h3><div class="pre">${ern.map(x=>`<a class="chip" href="#/asset/${encodeURIComponent(x.symbol)}">${esc(x.symbol)}</a>`).join('')}</div></div>`:''}
  <div class="wsn" style="margin-top:14px">Updated ${new Date(b.updated||Date.now()).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}. Prices may be delayed. Come back tomorrow for the next brief.</div><div style="margin-top:14px"><button class="btn" onclick="BRSHARE()">Share today’s brief</button></div>`}).catch(()=>{const el=document.getElementById('brb');if(el)el.innerHTML=EMPTY('Today’s brief is unavailable right now. Check back soon.')})};

